dashboard.definition:
{
    "title": "Interfaces and eHealth",
    "description": "Integration engine channels with throughput, queue and latency plus the health of the Austrian eHealth services",
    "inputs": {
        "input_time": {
            "type": "input.timerange",
            "title": "Time range",
            "options": {
                "token": "global_time",
                "defaultValue": "-4h@m,now"
            }
        }
    },
    "defaults": {
        "dataSources": {
            "ds.search": {
                "options": {
                    "queryParameters": {
                        "earliest": "$global_time.earliest$",
                        "latest": "$global_time.latest$"
                    }
                }
            }
        },
        "tokens": {
            "default": {
                "channel": {
                    "value": "*"
                }
            }
        }
    },
    "dataSources": {
        "ds_hl7": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_en_metrics metric_name IN (\"sakh.hl7.messages_in\", \"sakh.hl7.queue_depth\", \"sakh.hl7.avg_latency_ms\", \"sakh.hl7.ack_errors\") BY metric_name channel source_system target_system span=5m",
                "enableSmartSources": true
            },
            "name": "HL7 metrics (5 min)"
        },
        "ds_flow": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:hl7:engine\" earliest=-5m\n| stats sum(messages_in) as messages latest(queue_depth) as queue_depth latest(avg_latency_ms) as avg_latency_ms latest(status) as status latest(message_type) as message_type by channel source_system target_system",
                "enableSmartSources": true
            },
            "name": "Channels now"
        },
        "ds_k_msgs": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_hl7",
                "query": "| where metric_name=\"sakh.hl7.messages_in\" | timechart span=5m sum(v) as \"Messages/min\""
            }
        },
        "ds_k_queue": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_hl7",
                "query": "| where metric_name=\"sakh.hl7.queue_depth\" | timechart span=5m sum(v) as Queue"
            }
        },
        "ds_k_ack": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_hl7",
                "query": "| where metric_name=\"sakh.hl7.ack_errors\" | timechart span=5m sum(v) as \"ACK errors\""
            }
        },
        "ds_k_stopped": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_flow",
                "query": "| where status=\"stopped\" OR status=\"congested\" | stats count as \"Faulty channels\""
            }
        },
        "ds_k_elga": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.ehealth.error_pct\" span=15m | rename v as \"eHealth Error %\"",
                "enableSmartSources": true
            }
        },
        "ds_k_ecs": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.ehealth.avg_response_ms\" service=\"ecard_ecs\" span=15m | rename v as \"e-card ms\"",
                "enableSmartSources": true
            }
        },
        "ds_queue": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_hl7",
                "query": "| where metric_name=\"sakh.hl7.queue_depth\" AND channel=\"$channel$\" | timechart span=5m limit=0 max(v) by channel"
            }
        },
        "ds_latency": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_hl7",
                "query": "| where metric_name=\"sakh.hl7.avg_latency_ms\" AND channel=\"$channel$\" | timechart span=5m limit=0 avg(v) by channel"
            }
        },
        "ds_heat": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_hl7",
                "query": "| where metric_name=\"sakh.hl7.queue_depth\" | timechart span=5m limit=0 max(v) by channel"
            }
        },
        "ds_table": {
            "type": "ds.chain",
            "options": {
                "extend": "ds_flow",
                "query": "| eval Status=status\n| table channel source_system target_system message_type messages queue_depth avg_latency_ms Status\n| rename channel as Channel source_system as Source target_system as Target message_type as Message messages as \"Nachrichten (5 min)\" queue_depth as Queue avg_latency_ms as \"Latency ms\""
            }
        },
        "ds_eh": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:ehealth\" type=service earliest=-15m\n| stats latest(service_name) as Shift latest(requests) as \"Anfragen (5 min)\" latest(error_pct) as \"Error %\" latest(avg_response_ms) as \"Response ms\" latest(status) as Status by service | fields - service",
                "enableSmartSources": true
            }
        },
        "ds_eh_rt": {
            "type": "ds.search",
            "options": {
                "query": "| mstats avg(_value) as v WHERE index=demo_sakh_en_metrics metric_name=\"sakh.ehealth.avg_response_ms\" BY service_name span=15m | timechart span=15m avg(v) by service_name",
                "enableSmartSources": true
            }
        },
        "ds_docs": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:ehealth\" type=document | timechart span=30m count by status",
                "enableSmartSources": true
            }
        },
        "ds_doc_type": {
            "type": "ds.search",
            "options": {
                "query": "index=demo_sakh_en sourcetype=\"sakh:ehealth\" type=document | chart count over document_type by status",
                "enableSmartSources": true
            }
        }
    },
    "visualizations": {
        "viz_nav_home": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_home.svg",
                "preserveAspectRatio": true
            },
            "eventHandlers": [
                {
                    "type": "drilldown.linkToDashboard",
                    "options": {
                        "app": "kis_clinic",
                        "dashboard": "kis_home",
                        "tokens": [],
                        "newTab": false
                    }
                }
            ]
        },
        "viz_nav_care": {
            "type": "splunk.image",
            "options": {
                "src": "/static/app/kis_clinic/images/nav_care.svg",
