        "viz_01": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_msgs"
            },
            "options": {
                "majorColor": "#0f8f84",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            }
        },
        "viz_02": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_queue"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "below",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 50,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 50,
                        "to": 200,
                        "value": "#c98a00"
                    },
                    {
                        "from": 200,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_03": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_stopped"
            },
            "options": {
                "majorColor": "> majorValue | rangeValue(majorColorConfig)",
                "backgroundColor": "transparent",
                "sparklineDisplay": "off",
                "trendDisplay": "off",
                "numberPrecision": 0,
                "sparklineStrokeColor": "#0b7fab"
            },
            "context": {
                "majorColorConfig": [
                    {
                        "to": 1,
                        "value": "#1e8a5a"
                    },
                    {
                        "from": 1,
                        "to": 2,
                        "value": "#c98a00"
                    },
                    {
                        "from": 2,
                        "value": "#c8253f"
                    }
                ]
            }
        },
        "viz_04": {
            "type": "splunk.singlevalue",
            "dataSources": {
                "primary": "ds_k_ack"
