        "viz_07": {
            "type": "kis_clinic.hl7_flow",
            "dataSources": {
                "primary": "ds_flow"
            },
            "options": {
                "drilldownToken": "channel"
            },
            "eventHandlers": [
                {
                    "type": "drilldown.setToken",
                    "options": {
                        "tokens": [
                            {
                                "token": "channel",
                                "key": "value"
                            }
                        ]
                    }
                }
            ]
