        "viz_08": {
            "type": "kis_clinic.heat_timeline",
            "dataSources": {
                "primary": "ds_heat"
            },
            "options": {
                "scaleMode": "thresholds",
                "higherIsBetter": false,
                "warn": 50,
                "crit": 200,
                "maxSeries": 20,
                "decimals": 0,
                "drilldownToken": "channel"
            },
            "eventHandlers": [
