            "dataSources": {
                "primary": "ds_queue"
            },
            "options": {
                "backgroundColor": "transparent",
                "legendDisplay": "bottom",
                "xAxisTitleVisibility": "hide",
                "yAxisTitleVisibility": "hide",
                "seriesColors": [
                    "#0b7fab",
                    "#6b4fb3",
                    "#1e8a5a",
                    "#c98a00",
                    "#c8253f",
                    "#2f6fc4",
                    "#b8457c",
                    "#0f8f84",
                    "#d0661f",
                    "#9b3fae"
