                "lineWidth": 2
            }
        },
        "viz_11": {
            "type": "splunk.table",
            "dataSources": {
                "primary": "ds_table"
            },
            "options": {
                "backgroundColor": "transparent",
                "count": 14,
                "headerVisibility": "fixed",
                "fontSize": "small",
                "tableFormat": {
                    "rowBackgroundColors": "> table | seriesByIndex(0) | pick(rowBg)",
                    "headerBackgroundColor": "#e9eef4",
                    "rowColors": "#13294b",
                    "headerColor": "#5b6878"
                },
                "columnFormat": {
                    "Queue": {
                        "rowBackgroundColors": "> table | seriesByName(\"Queue\") | rangeValue(range_2)"
                    },
                    "Status": {
                        "rowBackgroundColors": "> table | seriesByName(\"Status\") | matchValue(statusBg)"
                    }
                }
            },
            "context": {
                "rowBg": [
